// Generated by AI
using System;
using System.Collections;
using UnityEngine;

// Keeps track of the current mission and updates the HUD when a mission is completed
public class MissionManager : MonoBehaviour
{
    // Data for one mission (texts come from the team's mission proposal)
    [Serializable]
    public class Mission
    {
        public string objective; // Short text shown in the HUD
        [TextArea(2, 4)] public string learning; // Historical fact learned in this mission
        public string factTitle; // Title of the optional "Did you know...?" window
        [TextArea(2, 4)] public string factBody; // Text of the optional window (leave empty to skip it)
    }

    [SerializeField] private HUDController hud; // HUD used to show objectives and windows
    [SerializeField] private string learningTitle = "Aprendizaje"; // Title of the learning window
    [SerializeField] private string finishedText = "Recorrido completado"; // HUD text after the last mission

    [SerializeField]
    private Mission[] missions =
    {
        new Mission
        {
            objective = "Misión 1: habla con el ciudadano del mercado",
            learning = "Existía desigualdad política y social entre los grupos de la sociedad colonial."
        },
        new Mission
        {
            objective = "Misión 2: investiga el florero con el comerciante",
            learning = "Los criollos buscaban una oportunidad para generar una protesta contra las autoridades españolas.",
            factTitle = "¿Sabías que...?",
            factBody = "Antonio Villavicencio fue una figura importante en el contexto del 20 de julio de 1810. Su recibimiento en Santa Fe fue el motivo que los criollos utilizaron para solicitar el famoso florero a José González Llorente."
        },
        new Mission
        {
            objective = "Misión 3: acércate a la plaza",
            learning = "El conflicto alrededor del florero desencadenó una protesta popular el 20 de julio de 1810."
        },
        new Mission
        {
            objective = "Misión 4: habla con los habitantes de la plaza",
            learning = "La protesta impulsó la organización de una Junta de Gobierno en Santa Fe."
        },
        new Mission
        {
            objective = "Misión 5: consulta qué decisiones se tomaron",
            learning = "El 20 de julio de 1810 marcó un paso fundamental en el proceso de Independencia, aunque esta no se consiguió definitivamente ese día.",
            factTitle = "¿Sabías que...?",
            factBody = "¡La Independencia no se logró en un solo día! Después del 20 de julio de 1810, continuaron varios años de luchas hasta la Batalla de Boyacá, el 7 de agosto de 1819, que fue decisiva para la independencia de la Nueva Granada."
        }
    };

    private int currentMission; // Index (0-based) of the active mission

    // Shows the first objective when the game starts
    private void Start()
    {
        ShowCurrentObjective();
    }

    // Called by an NPC when its dialogue ends. Only the active mission can be completed (1-based number)
    public void CompleteMission(int missionNumber)
    {
        if (currentMission >= missions.Length || missionNumber != currentMission + 1)
        {
            return;
        }
        StartCoroutine(CompleteRoutine());
    }

    // Shows the learning window, then the optional fact window, then the next objective
    private IEnumerator CompleteRoutine()
    {
        Mission finished = missions[currentMission];
        currentMission++; // Advance first so repeated calls are ignored

        if (hud != null)
        {
            if (!string.IsNullOrEmpty(finished.learning))
            {
                hud.ShowFact(learningTitle, finished.learning);
                yield return new WaitUntil(() => !hud.IsFactOpen); // The player closes it at their own pace
            }
            if (!string.IsNullOrEmpty(finished.factBody))
            {
                hud.ShowFact(finished.factTitle, finished.factBody);
                yield return new WaitUntil(() => !hud.IsFactOpen);
            }
        }
        ShowCurrentObjective();
    }

    // Updates the HUD with the active objective or the final text
    private void ShowCurrentObjective()
    {
        if (hud == null)
        {
            Debug.LogWarning("MissionManager: HUDController is not assigned.");
            return;
        }
        hud.SetMission(currentMission < missions.Length ? missions[currentMission].objective : finishedText);
    }
}